/* Scroll to top CSS */
.hfe-scroll-to-top-wrap.hfe-scroll-to-top-hide {
    display: none;
}

.hfe-scroll-to-top-wrap.edit-mode,
.hfe-scroll-to-top-wrap.single-page-off {
    display: none !important;
}

.hfe-scroll-to-top-button {
    position:fixed;
    right:15px;
    bottom:15px;
    z-index:9999;
    display:-webkit-box;
    display:-webkit-flex;
    display:-ms-flexbox;
    display:flex;
    -webkit-box-align:center;
    -webkit-align-items:center;
    align-items:center;
    -ms-flex-align:center;
    -webkit-box-pack:center;
    -ms-flex-pack:center;
    -webkit-justify-content:center;
    justify-content:center;
    width:50px;
    height:50px;
    border-radius:50px;
    background-color:var(--original-color-25);
    color:var(--original-color-24);
    text-align:center;
    opacity:1;
    cursor:pointer;
    -webkit-transition:all .3s;
    transition:all .3s;
}

.hfe-scroll-to-top-button i {
    color:var(--original-color-24);
    font-size:16px;
}
/* Breadcrumbs CSS */

ul.hfe-breadcrumbs {
    display:block;
    margin:0;
    padding:0;
    list-style:none
}

ul.hfe-breadcrumbs li {
    display: inline-block;
    margin-right: 10px;
    vertical-align: middle;
}

ul.hfe-breadcrumbs li:last-child {
    margin:0;
}

ul.hfe-breadcrumbs li a,
ul.hfe-breadcrumbs li span.hfe-breadcrumbs-separator-icon,
ul.hfe-breadcrumbs li span.hfe-breadcrumbs-text{
    display:block;
}

ul.hfe-breadcrumbs li span.hfe-breadcrumbs-text{
    -webkit-transition:all .4s;
    transition:all .4s;
}

span.hfe-breadcrumbs-home-icon{
    margin-right:10px;
    align-content: center;
}

.hfe-breadcrumbs-first a {
    align-content: center;
}

.hfe-breadcrumbs-separator-icon i, 
.hfe-breadcrumbs-separator-icon svg,
.hfe-breadcrumbs-home-icon i,
.hfe-breadcrumbs-home-icon svg {
    width: 1em;
    height: 1em;
    position: relative;
    display: block;
}

ul.hfe-breadcrumbs-show-home li.hfe-breadcrumbs-first {
    display: inline-flex;
}

/* Post Info CSS */

ul.hfe-post-info-items {
    list-style: none;
    margin: 0;
    padding: 0;
}

ul.hfe-post-info-inline.hfe-post-info-items {
    display: -webkit-box;
    display: -webkit-flex;
    display: -ms-flexbox;
    display: flex;
    -webkit-flex-wrap: wrap;
    -ms-flex-wrap: wrap;
    flex-wrap: wrap;
}

li.hfe-post-info-item {
    -webkit-align-content: center;
    -ms-flex-line-pack: center;
    align-content: center;
    -webkit-box-orient: horizontal;
    -webkit-box-direction: normal;
    -webkit-flex-direction: row;
    -ms-flex-direction: row;
    flex-direction: row;
    -webkit-flex-wrap: nowrap;
    -ms-flex-wrap: nowrap;
    flex-wrap: nowrap;
    -webkit-box-pack: center;
    -ms-flex-pack: center;
    -webkit-justify-content: center;
    justify-content: center;
}

li.hfe-post-info-item,
li.hfe-post-info-item > a {
    display: -webkit-box;
    display: -webkit-flex;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-align: center;
    -webkit-align-items: center;
    align-items: center;
    -ms-flex-align: center;
}

.hfe-post-info-inline.hfe-post-info-items .hfe-post-info-item {
    margin-right: 8px;
    margin-left: 8px;
}

.hfe-post-info-inline .hfe-post-info-item:not(:last-child):after {
    position: relative;
    right: -8px;
}

.hfe-post-info-inline.hfe-post-info-items {
    margin-right: -8px;
    margin-left: -8px;
}

.hfe-post-info-icon svg {
    display: block;
}

.hfe-post-info-layout-traditional .hfe-post-info-item:not(:last-child):after {
    position: absolute;
    bottom: 0;
    width: 100%;
    left: 0;
}

.hfe-post-info-layout-traditional .hfe-post-info-item:not(:last-child) {
    position: relative;
}


/* Info Card CSS */
.hfe-icon-wrap .hfe-icon svg {
    height: 100%;
    width: 100%;
}
body .elementor .hfe-button-wrapper a {
    text-decoration: none;
}
.hfe-button-wrapper {
    border-radius: 3px;
}


.hfe-reading-progress-bar{
    height: 4px;
}

/* Basic Posts Widget CSS - Only essential structure, no styling */
.hfe-posts-grid {
    display: grid;
}

.hfe-post-image img {
    width: 100%;
    height: auto;
    display: block;
}

.hfe-post-title a {
    text-decoration: none;
}
.hfe-post-title {
    margin-top: 0px;
}
.hfe-read-more {
    text-decoration: none;
}
.hfe-post-meta {
    font-size: 12px;
    line-height: 1.3em;
}
.hfe-post-title {
    font-size: 20px;
}

/* HFE Woo Products Widget Styles */
.hfe-woo-products-wrapper {
	width: 100%;
}

.hfe-woo-products-grid {
	display: grid;
	grid-template-columns: repeat(4, 1fr);
	gap: 35px 20px;
}

.hfe-product-item {
	background: var(--original-color-229);
	border-radius: 8px;
	overflow: hidden;
	border: 1px solid var(--original-color-192);
}


.hfe-product-image {
	position: relative;
	overflow: hidden;
}

.hfe-product-image img {
	width: 100%;
	height: auto;
	display: block;
}


.hfe-product-content {
	padding: 20px;
	display: flex;
	flex-direction: column;
	height: 100%;
}

.hfe-product-category {
	font-size: 12px;
	text-transform: uppercase;
	letter-spacing: 0.8px;
	margin-bottom: 8px;
	opacity: 0.75;
	font-weight: 500;
	color: var(--original-color-8);
}

.hfe-product-title {
	margin: 0 0 12px 0;
	font-size: 16px;
	line-height: 1.5;
	font-weight: 600;
	flex-grow: 1;
}

.hfe-product-title a {
	color: var(--original-color-4);
	text-decoration: none;
}

.hfe-product-title h2 {
	margin: 0;
	font-size: inherit;
	line-height: inherit;
	font-weight: inherit;
	color: inherit;
}

.hfe-product-title .hfe-loop-product__link {
	display: block;
}


.hfe-product-rating {
	margin-bottom: 12px;
}

.hfe-product-rating .review-rating {
	display: flex;
	align-items: center;
	min-height: 16px;
}

.hfe-product-rating .star-rating {
	font-size: 14px;
	color: var(--original-color-219);
	display: inline-block;
}

.hfe-product-price {
	margin-bottom: 16px;
	font-weight: 700;
	font-size: 18px;
}

.hfe-product-price .price {
	color: var(--original-color-4);
}

.hfe-product-price .price del {
	opacity: 0.6;
	margin-right: 8px;
	font-weight: 400;
}

.hfe-product-description {
	margin-bottom: 16px;
	font-size: 14px;
	line-height: 1.6;
	color: var(--original-color-8);
	flex-grow: 1;
}

.hfe-product-add-to-cart {
	margin-top: auto;
}

.hfe-woo-products-wrapper .hfe-product-add-to-cart .button {
	width: auto;
	min-width: 100px;
	padding: 12px 20px;
	border: none;
	border-radius: 4px;
	font-size: 14px;
	font-weight: 600;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	cursor: pointer;
	text-decoration: none;
	display: inline-block;
	text-align: center;
}

.hfe-woo-products-wrapper .hfe-product-add-to-cart .button:hover,
.hfe-woo-products-wrapper .hfe-product-add-to-cart .button:focus,
.hfe-woo-products-wrapper .hfe-product-add-to-cart .button:active,
.hfe-woo-products-wrapper .hfe-product-add-to-cart a.button:link {
	text-decoration: none;
}


.hfe-woo-products-notice,
.hfe-woo-products-empty {
	text-align: center;
	padding: 40px 20px;
	background: var(--original-color-207);
	border-radius: 4px;
	color: var(--original-color-8);
}

/* Card Hover Effects */
.hfe-product-item {
	height: 100%;
	display: flex;
	flex-direction: column;
}

.hfe-product-content {
	flex: 1;
	display: flex;
	flex-direction: column;
}

/* Content Alignment Classes */
.hfe-content-align-left .hfe-product-item {
	text-align: left;
}

.hfe-content-align-left .hfe-product-item .star-rating {
	margin-left: 0;
	margin-right: auto;
}

.hfe-content-align-center .hfe-product-item {
	text-align: center;
}

.hfe-content-align-center .hfe-product-item .star-rating {
	margin-left: auto;
	margin-right: auto;
}

.hfe-content-align-right .hfe-product-item {
	text-align: right;
}

.hfe-content-align-right .hfe-product-item .star-rating {
	margin-left: auto;
	margin-right: 0;
}

/* Tablet Responsive Alignment */
@media (max-width: 1024px) {
	.hfe-content-tablet-align-left .hfe-product-item {
		text-align: left;
	}

	.hfe-content-tablet-align-left .hfe-product-item .star-rating {
		margin-left: 0;
		margin-right: auto;
	}

	.hfe-content-tablet-align-center .hfe-product-item {
		text-align: center;
	}

	.hfe-content-tablet-align-center .hfe-product-item .star-rating {
		margin-left: auto;
		margin-right: auto;
	}

	.hfe-content-tablet-align-right .hfe-product-item {
		text-align: right;
	}

	.hfe-content-tablet-align-right .hfe-product-item .star-rating {
		margin-left: auto;
		margin-right: 0;
	}
}

/* Mobile Responsive Alignment */
@media (max-width: 767px) {
	.hfe-content-mobile-align-left .hfe-product-item {
		text-align: left;
	}

	.hfe-content-mobile-align-left .hfe-product-item .star-rating {
		margin-left: 0;
		margin-right: auto;
	}

	.hfe-content-mobile-align-center .hfe-product-item {
		text-align: center;
	}

	.hfe-content-mobile-align-center .hfe-product-item .star-rating {
		margin-left: auto;
		margin-right: auto;
	}

	.hfe-content-mobile-align-right .hfe-product-item {
		text-align: right;
	}

	.hfe-content-mobile-align-right .hfe-product-item .star-rating {
		margin-left: auto;
		margin-right: 0;
	}
}

/* Responsive Design */
@media (max-width: 1200px) {
	.hfe-woo-products-grid {
		grid-template-columns: repeat(3, 1fr);
	}
}

@media (max-width: 768px) {
	.hfe-woo-products-grid {
		grid-template-columns: repeat(2, 1fr);
		gap: 20px 15px;
	}
	
	.hfe-product-content {
		padding: 16px;
	}
	
	.hfe-product-title {
		font-size: 15px;
	}
	
	.hfe-product-price {
		font-size: 16px;
	}
}

@media (max-width: 480px) {
	.hfe-woo-products-grid {
		grid-template-columns: 1fr;
		gap: 25px;
	}
	
	.hfe-product-content {
		padding: 18px;
	}
}

