.wpvr-frontend-text-overlay,
.wpvr-frontend-text-overlay__body,
.wpvr-frontend-text-overlay__content {
  text-align: left;
}

.wpvr-frontend-text-overlay * {
  user-select: text;
  -webkit-user-select: text;
}

.wpvr-frontend-text-overlay__body {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  box-sizing: border-box;
  -webkit-overflow-scrolling: touch;
  text-align: left;
}

/* Custom sleek scrollbar for overlay body */
.wpvr-frontend-text-overlay__body::-webkit-scrollbar {
  width: 5px;
}
.wpvr-frontend-text-overlay__body::-webkit-scrollbar-track {
  background: transparent;
}
.wpvr-frontend-text-overlay__body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.25);
  border-radius: 4px;
}
.wpvr-frontend-text-overlay__body::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.45);
}

.wpvr-frontend-text-overlay__content {
  position: absolute;
  box-sizing: border-box;
  line-height: 1.55;
  color: var(--original-color-229);
  word-break: break-word;
  padding-bottom: 24px;
  text-align: left;
}

.wpvr-frontend-text-overlay__content * {
  max-width: 100%;
  box-sizing: border-box;
}

.wpvr-frontend-text-overlay__content p {
  margin: 0 0 10px 0;
  text-align: left;
}
.wpvr-frontend-text-overlay__content p:last-child {
  margin-bottom: 0;
}

.wpvr-frontend-text-overlay__content h1,
.wpvr-frontend-text-overlay__content h2,
.wpvr-frontend-text-overlay__content h3,
.wpvr-frontend-text-overlay__content h4,
.wpvr-frontend-text-overlay__content h5,
.wpvr-frontend-text-overlay__content h6 {
  margin: 0 0 8px 0;
  line-height: 1.25;
  color: inherit;
  font-weight: 700;
  text-align: left;
}

.wpvr-frontend-text-overlay__content ul,
.wpvr-frontend-text-overlay__content ol {
  margin: 0 0 10px 0;
  padding-left: 20px;
}

.wpvr-frontend-text-overlay__content li {
  margin-bottom: 4px;
}

.wpvr-frontend-text-overlay__content blockquote {
  margin: 0 0 10px 0;
  padding: 4px 12px;
  border-left: 3px solid rgba(255, 255, 255, 0.45);
  font-style: italic;
}

.wpvr-frontend-text-overlay__content a {
  color: var(--original-color-109);
  text-decoration: underline;
  text-underline-offset: 2px;
  transition: color 0.15s ease;
}
.wpvr-frontend-text-overlay__content a:hover {
  color: var(--original-color-136);
}

.wpvr-frontend-text-overlay__content img {
  border-radius: 6px;
  height: auto;
}

/* Close button */
.wpvr-text-overlay-close-btn {
  position: absolute;
  /* Follow the top-right curve without leaving small overlays. */
  top: min(var(--wpvr-overlay-close-inset, 12px), max(0px, calc(50% - 14px)));
  right: min(var(--wpvr-overlay-close-inset, 12px), max(0px, calc(50% - 14px)));
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: var(--original-color-229);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  margin: 0;
  z-index: 35 !important;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: background 0.15s ease, transform 0.15s ease, color 0.15s ease;
}

.wpvr-text-overlay-close-btn:hover {
  background: rgba(0, 0, 0, 0.75);
  transform: scale(1.08);
  color: var(--original-color-229);
}

.wpvr-text-overlay-close-btn:focus-visible {
  outline: 2px solid var(--original-color-229);
  outline-offset: 2px;
}

/* Reopen button */
.wpvr-text-overlay-reopen-btn {
  position: absolute;
  z-index: 35 !important;
  pointer-events: auto !important;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 13px;
  background: rgba(20, 20, 25, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 9999px;
  color: var(--original-color-229);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
  user-select: none;
  -webkit-user-select: none;
}

.wpvr-text-overlay-reopen-btn:hover {
  background: rgba(30, 30, 42, 0.95);
  transform: translateY(-1px) scale(1.03);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.45);
}

.wpvr-text-overlay-reopen-btn:focus-visible {
  outline: 2px solid var(--original-color-229);
  outline-offset: 2px;
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .wpvr-frontend-text-overlay--template-left {
    min-width: min(85%, 320px) !important;
  }
  .wpvr-frontend-text-overlay--template-right {
    min-width: min(85%, 320px) !important;
    left: auto !important;
    right: 0 !important;
  }
  .wpvr-frontend-text-overlay--template-top,
  .wpvr-frontend-text-overlay--template-bottom {
    min-height: min(60%, 260px) !important;
  }
}


