.alert-wrapper {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  margin: 0px auto;
  padding: 0px auto;
  left: 0;
  top: 0;
  overflow: hidden;
  position: fixed;
  background: rgb(0, 0, 0, 0.3);
  z-index: 999999;
}

@keyframes open-frame {
  0% {
    transform: scale(1);
  }
  25% {
    transform: scale(0.95);
  }
  50% {
    transform: scale(0.97);
  }
  75% {
    transform: scale(0.93);
  }
  100% {
    transform: scale(1);
  }
}

.alert-frame {
  background: var(--original-color-24);
  min-height: 350px;
  width: 300px;
  box-shadow: 5px 5px 10px rgb(0, 0, 0, 0.2);
  border-radius: 10px;
  animation: open-frame 0.3s linear;
}

.alert-header {
  display: flex;
  flex-direction: row;
  height: 175px;
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
}

.alert-header-base {
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
}

.custom-img-wrapper {
  min-height: 145px;
  max-height: 20rem;
  overflow: scroll;
  display: flex;
  align-items: center;
  justify-content: center;
}

.alert-img {
  height: 80px;
  position: absolute;
  left: 0;
  right: 0;
  margin-left: auto;
  margin-right: auto;
  align-self: center;
}

.alert-close {
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Dosis', sans-serif;
  font-weight: 700;
  cursor: pointer;
  line-height: 30px;
}

.alert-close-default {
  color: rgb(0, 0, 0, 0.2);
  font-size: 16px;
  transition: color 0.5s;
  margin-left: auto;
  margin-right: 5px;
  margin-top: 5px;
}

.alert-close-circle {
  background: var(--original-color-179);
  color: var(--original-color-3);
  border-radius: 17.5px;
  margin-top: -15px;
  margin-right: -15px;
  font-size: 12px;
  transition: background 0.5s;
  margin-left: auto;
}

.alert-close-circle:hover {
  background: var(--original-color-24);
}

.alert-close:hover {
  color: rgb(0, 0, 0, 0.5);
}

.alert-body {
  padding: 30px 30px;
  display: flex;
  flex-direction: column;
  text-align: center;
}

.alert-title {
  font-size: 18px !important;
  font-family: 'Open Sans', sans-serif;
  font-weight: 700;
  font-size: 15px;
  margin-bottom: 35px;
  color: var(--original-color-3);
  align-self: center;
}

.alert-message {
  font-size: 15px !important;
  color: var(--original-color-8);
  font-family: 'Open Sans', sans-serif;
  font-weight: 400;
  font-size: 15px;
  text-align: center;
  line-height: 1.6;
  align-self: center;
}

.alert-button {
  min-width: 140px;
  height: 35px;
  border-radius: 20px;
  font-family: 'Open Sans', sans-serif;
  font-weight: 400;
  font-size: 15px;
  color: white;
  border: none;
  cursor: pointer;
  transition: background 0.5s;
  padding: 0 15px;
  align-self: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.alert-button:focus {
  outline: 0;
}

.question-buttons {
  display: flex;
  flex-direction: row;
  justify-content: center;
}

.confirm-button {
  min-width: 100px;
  height: 35px;
  border-radius: 20px;
  font-family: 'Open Sans', sans-serif;
  font-weight: 400;
  font-size: 15px;
  color: white;
  border: none;
  cursor: pointer;
  transition: background 0.5s;
  padding: 0 15px;
  margin-right: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.confirm-button:focus {
  outline: 0;
}

.cancel-button {
  min-width: 100px;
  height: 35px;
  border-radius: 20px;
  font-family: 'Open Sans', sans-serif;
  font-weight: 400;
  font-size: 15px;
  color: white;
  border: none;
  cursor: pointer;
  padding: 0;
  line-height: 1.6;
  transition: background 0.5s;
  padding: 0 15px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.cancel-button:focus {
  outline: 0;
}

@keyframes open-toast {
  0% {
    transform: scaleX(1) scaleY(1);
  }
  20%,
  45% {
    transform: scaleX(1.35) scaleY(0.1);
  }
  65% {
    transform: scaleX(0.8) scaleY(1.7);
  }
  80% {
    transform: scaleX(0.6) scaleY(0.85);
  }
  100% {
    transform: scaleX(1) scaleY(1);
  }
}

.toast-container {
  display: flex;
  flex-direction: column;
  top: 15px;
  right: 15px;
  position: fixed;
  z-index: 999999;
}

.toast-content {
  overflow: hidden;
  border-radius: 5px;
  box-shadow: 0 0 20px rgb(0, 0, 0, 0.2);
  animation: open-toast 0.3s linear;
}

.toast-content + .toast-content {
  margin-top: 10px;
}

.toast-frame {
  padding: 5px 15px;
  display: flex;
  min-width: 100px;
  height: 70px;
  border-top-left-radius: 10px;
  border-top-right-radius: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.toast-body-img {
  height: 40px;
}

.toast-body {
  display: flex;
  align-items: center;
  width: 100%;
}

.toast-body-content {
  display: flex;
  flex-direction: column;
  width: 100%;
}

.toast-title {
  font-size: 16px !important;
  font-family: 'Open Sans', sans-serif;
  font-weight: bold;
  font-size: 15px;
  color: var(--original-color-24);
  margin-left: 15px;
}

.toast-message {
  font-size: 13px !important;
  font-family: 'Open Sans', sans-serif;
  font-weight: 600;
  font-size: 15px;
  color: var(--original-color-24);
  margin-left: 15px;
}

.toast-close {
  color: rgb(0, 0, 0, 0.2);
  font-family: 'Dosis', sans-serif;
  font-weight: 700;
  font-size: 16px;
  cursor: pointer;
  transition: color 0.5s;
  margin-left: 25px;
}

@keyframes timer {
  0% {
    width: 100%;
  }
  25% {
    width: 75%;
  }
  50% {
    width: 50%;
  }
  75% {
    width: 25%;
  }
  100% {
    width: 1%;
  }
}

.toast-timer {
  width: 1%;
  height: 5px;
}

.toast-close:hover {
  color: rgb(0, 0, 0, 0.5);
}

.error-bg {
  background: var(--original-color-170);
}

.success-bg {
  background: var(--original-color-76);
}

.warning-bg {
  background: var(--original-color-209);
}

.question-bg {
  background: var(--original-color-123);
}

.error-btn:hover {
  background: var(--original-color-180);
}

.success-btn:hover {
  background: var(--original-color-116);
}

.warning-btn:hover {
  background: var(--original-color-214);
}

.info-btn:hover {
  background: var(--original-color-157);
}

.question-btn:hover {
  background: var(--original-color-152);
}

.error-timer {
  background: var(--original-color-180);
}

.success-timer {
  background: var(--original-color-116);
}

.warning-timer {
  background: var(--original-color-214);
}

.info-timer {
  background: var(--original-color-157);
}

.info-bg {
  background: var(--original-color-132);
}

